import express from 'express';
import { Pool } from 'pg';
import crypto from 'crypto';

const app = express();
app.use(express.json());

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  ssl: { rejectUnauthorized: true }
});

// Middleware to extract user context from JWT (simplified)
function extractUser(req, res, next) {
  const token = req.headers['x-auth-token'];
  if (!token) return res.status(401).json({ error: 'unauthorized' });
  // In production, this would verify JWT signature
  try {
    const payload = Buffer.from(token.split('.')[1], 'base64').toString();
    req.user = JSON.parse(payload);
    next();
  } catch (e) {
    return res.status(401).json({ error: 'invalid token' });
  }
}

// Search endpoint with filtering
app.get('/api/v2/documents/search', extractUser, async (req, res) => {
  const { q, sort_by, order, tenant_id } = req.query;

  // Tenant isolation check
  if (tenant_id && tenant_id !== req.user.tenant_id) {
    return res.status(403).json({ error: 'cross-tenant access denied' });
  }

  const effectiveTenant = tenant_id || req.user.tenant_id;

  // Build query with user-controlled sort
  let query = `SELECT id, title, created_at, classification 
               FROM documents 
               WHERE tenant_id = $1 
               AND (title ILIKE $2 OR content ILIKE $2)`;

  const params = [effectiveTenant, `%${q || ''}%`];

  // Sort injection vector - sort_by is not parameterizable in pg
  const allowedSorts = ['created_at', 'title', 'id'];
  let sortClause = 'created_at';

  if (sort_by) {
    // Developer thought this was sufficient validation
    if (sort_by.length < 64 && /^[a-zA-Z0-9_,() ]+$/.test(sort_by)) {
      sortClause = sort_by;
    }
  }

  const direction = order === 'asc' ? 'ASC' : 'DESC';
  query += ` ORDER BY ${sortClause} ${direction} LIMIT 50`;

  try {
    const result = await pool.query(query, params);
    // Filter out classified documents from response
    const filtered = result.rows.map(row => {
      if (row.classification === 'SECRET' && req.user.clearance < 3) {
        return { id: row.id, title: '[REDACTED]', created_at: row.created_at };
      }
      return row;
    });
    res.json({ results: filtered, count: filtered.length });
  } catch (e) {
    console.error('Search error:', e.message);
    res.status(500).json({ error: 'search failed' });
  }
});

// Document detail endpoint
app.get('/api/v2/documents/:id', extractUser, async (req, res) => {
  const result = await pool.query(
    'SELECT * FROM documents WHERE id = $1 AND tenant_id = $2',
    [req.params.id, req.user.tenant_id]
  );
  if (result.rows.length === 0) return res.status(404).json({ error: 'not found' });
  res.json(result.rows[0]);
});

app.listen(process.env.PORT || 3000);
